int save(FILE *handle) { /* called by mccode_main for hollow_cylinder:SAVE */
  if (!handle) siminfo_init(NULL);

  /* call iteratively all components SAVE */
  class_Progress_bar_save(&_origin_var);


  class_PSD_monitor_save(&_before_var);








  class_PSD_monitor_save(&_after_var);

  class_PSD_monitor_4PI_save(&_mon_4pi_var);

  if (!handle) siminfo_close(); 

  return(0);
} /* save */

