int finally(void) { /* called by mccode_main for hollow_cylinder:FINALLY */
#pragma acc update host(_origin_var)
#pragma acc update host(_src_var)
#pragma acc update host(_before_var)
#pragma acc update host(_init_var)
#pragma acc update host(_sample_inc_var)
#pragma acc update host(_sample_mat_var)
#pragma acc update host(_hollow_cylinder_shell_var)
#pragma acc update host(_inner_vacuum_var)
#pragma acc update host(_master_var)
#pragma acc update host(_stop_var)
#pragma acc update host(_after_var)
#pragma acc update host(_mon_4pi_var)
#pragma acc update host(_instrument_var)

  siminfo_init(NULL);
  save(siminfo_file); /* save data when simulation ends */

  /* call iteratively all components FINALLY */
  class_Progress_bar_finally(&_origin_var);

  class_Source_gen_finally(&_src_var);

  class_PSD_monitor_finally(&_before_var);


  class_Incoherent_process_finally(&_sample_inc_var);

  class_Union_make_material_finally(&_sample_mat_var);



  class_Union_master_finally(&_master_var);


  class_PSD_monitor_finally(&_after_var);

  class_PSD_monitor_4PI_finally(&_mon_4pi_var);

  siminfo_close(); 

  return(0);
} /* finally */

