int _getcomp_index(char* compname)
/* Enables retrieving the component position & rotation when the index is not known.
 * Component indexing into MACROS, e.g., POS_A_COMP_INDEX, are 1-based! */
{
  if (!strcmp(compname, "origin")) return 1;
  if (!strcmp(compname, "src")) return 2;
  if (!strcmp(compname, "before")) return 3;
  if (!strcmp(compname, "init")) return 4;
  if (!strcmp(compname, "sample_inc")) return 5;
  if (!strcmp(compname, "sample_mat")) return 6;
  if (!strcmp(compname, "hollow_cylinder_shell")) return 7;
  if (!strcmp(compname, "inner_vacuum")) return 8;
  if (!strcmp(compname, "master")) return 9;
  if (!strcmp(compname, "stop")) return 10;
  if (!strcmp(compname, "after")) return 11;
  if (!strcmp(compname, "mon_4pi")) return 12;
  return -1;
}

